try {
    const savedPsPlus = typeof localStorage !== 'undefined' ? localStorage.getItem('zd_ps_plus_plans') : null;
    if (savedPsPlus) {
        const parsed = JSON.parse(savedPsPlus);
        ['PS5', 'PS4'].forEach(platform => {
            if (parsed[platform]) {
                ['essential', 'extra', 'deluxe'].forEach(tier => {
                    if (parsed[platform][tier] && parsed[platform][tier].prices) {
                        PS_PLUS_PLANS[platform][tier].prices = {
                            ...PS_PLUS_PLANS[platform][tier].prices,
                            ...parsed[platform][tier].prices
                        };
                    }
                });
            }
        });
    }
} catch (e) {
    console.warn("No se pudieron cargar precios locales de PS Plus:", e);
}


